1	"use client";
2	
3	import { useState } from "react";
4	import { useQuery, useQueryClient } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	import { Button } from "@/components/ui/button";
7	import { Input } from "@/components/ui/input";
8	import { Label } from "@/components/ui/label";
9	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
10	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
11	import { Switch } from "@/components/ui/switch";
12	import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
13	import { Badge } from "@/components/ui/badge";
14	import { Textarea } from "@/components/ui/textarea";
15	import { toast } from "sonner";
16	import { Plus, Pencil, Save, Trash2, Loader2, CheckCircle, AlertTriangle, Archive, RotateCcw, RefreshCw, Link2, ExternalLink } from "lucide-react";
17	import ConfirmDialog from "./ConfirmDialog";
18	import { logAuditAction } from "@/lib/auditLog";
19	
20	const parseFunctionError = (error: any) => {
21	  const message = error?.message || "";
22	  const jsonStart = message.indexOf("{");
23	  if (jsonStart === -1) return null;
24	  try {
25	    return JSON.parse(message.slice(jsonStart));
26	  } catch {
27	    return null;
28	  }
29	};
30	
31	const syncDodoProduct = async (action: string, payload: any) => {
32	  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
33	    body: { action, type: "plan", ...payload },
34	  });
35	  if (error) {
36	    const parsed = parseFunctionError(error);
37	    if (parsed?.not_found) return parsed;
38	    throw error;
39	  }
40	  if (data?.not_found) return data;
41	  if (data?.error) throw new Error(data.error);
42	  return data;
43	};
44	
45	const PlansTab = () => {
46	  const qc = useQueryClient();
47	  const [saving, setSaving] = useState(false);
48	  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string; dodo_product_id?: string; dodo_credit_entitlement_id?: string; paymentCount?: number } | null>(null);
49	  const [showArchived, setShowArchived] = useState(false);
50	  const [verifying, setVerifying] = useState<string | null>(null);
51	  const [verifyResults, setVerifyResults] = useState<Record<string, { exists: boolean; is_active?: boolean; dodo_name?: string }>>({});
52	
53	  const { data: plans } = useQuery({
54	    queryKey: ["admin_plans"],
55	    queryFn: async () => {
56	      const { data, error } = await supabase.from("plans").select("*").order("created_at");
57	      if (error) throw error;
58	      // The plans view exposes a subset of columns; the actual table has
59	      // additional fields (dodo_product_id, active, credits, etc.) that the
60	      // admin UI needs. Cast to preserve runtime access.
61	      return data as unknown as Record<string, unknown>[];
62	    },
63	  });
64	
65	  // Get payment counts for archived plans (for delete eligibility)
66	  const { data: paymentCounts } = useQuery({
67	    queryKey: ["admin_plan_payment_counts"],
68	    queryFn: async () => {
69	      const { data, error } = await supabase
70	        .from("payments")
71	        .select("plan_id")
72	        .not("plan_id", "is", null);
73	      if (error) throw error;
74	      const counts: Record<string, number> = {};
75	      data?.forEach((p: any) => { counts[p.plan_id] = (counts[p.plan_id] || 0) + 1; });
76	      return counts;
77	    },
78	  });
79	
80	  const activePlans = plans?.filter((p: any) => p.active) ?? [];
81	  const archivedPlans = plans?.filter((p: any) => !p.active) ?? [];
82	
83	  const [editPlan, setEditPlan] = useState<any>(null);
84	  const [form, setForm] = useState({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05", description: "" });
85	
86	  const openNew = () => {
87	    setForm({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05", description: "" });
88	    setEditPlan("new");
89	  };
90	
91	  const openEdit = (p: any) => {
92	    setForm({ name: p.name, price: String(p.price), credits: String(p.credits), billing_type: p.billing_type, active: p.active, per_resume_cost: String(p.per_resume_cost ?? 0.05), description: p.description || "" });
93	    setEditPlan(p);
94	  };
95	
96	  const validate = () => {
97	    if (!form.name.trim()) { toast.error("Plan name is required"); return false; }
98	    if (!form.price || parseFloat(form.price) <= 0) { toast.error("Price must be greater than 0"); return false; }
99	    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
100	    if (parseFloat(form.per_resume_cost) < 0) { toast.error("Per resume cost cannot be negative"); return false; }
101	    return true;
102	  };
103	
104	  const handleVerify = async (planId: string, productId: string) => {
105	    setVerifying(productId);
106	    try {
107	      const result = await syncDodoProduct("verify", { product_id: productId });
108	      setVerifyResults(prev => ({ ...prev, [productId]: result }));
109	      if (result.exists && result.is_active) {
110	        toast.success("Product verified on Dodo ✓");
111	      } else if (result.exists && !result.is_active) {
112	        toast.warning("Product exists on Dodo but is archived/inactive");
113	      } else {
114	        await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null } as Record<string, unknown>).eq("id", planId);
115	        qc.invalidateQueries({ queryKey: ["admin_plans"] });
116	        toast.error("Product not found on Dodo — link cleared automatically");
117	      }
118	    } catch (err: any) {
119	      toast.error("Verify failed: " + (err.message || "Unknown error"));
120	    } finally {
121	      setVerifying(null);
122	    }
123	  };
124	
125	  const handleSyncToDodo = async (plan: any) => {
126	    setSaving(true);
127	    try {
128	      const dodoResult = await syncDodoProduct("create", {
129	        name: plan.name,
130	        price: plan.price,
131	        credits: plan.credits,
132	        billing_type: plan.billing_type,
133	        description: plan.description || "",
134	      });
135	      if (dodoResult.product_id) {
136	        const updateData: any = { dodo_product_id: dodoResult.product_id };
137	        if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
138	        await supabase.from("plans").update(updateData as Record<string, unknown>).eq("id", plan.id);
139	        toast.success("Plan synced with Dodo ✓");
140	        qc.invalidateQueries({ queryKey: ["admin_plans"] });
141	      }
142	    } catch (err: any) {
143	      toast.error("Dodo sync failed: " + (err.message || "Unknown error"));
144	    } finally {
145	      setSaving(false);
146	    }
147	  };
148	
149	  const save = async () => {
150	    if (!validate()) return;
151	    setSaving(true);
152	    try {
153	      const payload = {
154	        name: form.name.trim(),
155	        price: parseFloat(form.price),
156	        credits: parseInt(form.credits),
157	        billing_type: form.billing_type,
158	        active: form.active,
159	        per_resume_cost: parseFloat(form.per_resume_cost),
160	      } as any;
161	
162	      if (editPlan === "new") {
163	        const { data: inserted, error } = await supabase.from("plans").insert(payload).select().single();
164	        if (error) { toast.error(error.message); return; }
165	
166	        try {
167	          const dodoResult = await syncDodoProduct("create", {
168	            name: form.name.trim(),
169	            price: parseFloat(form.price),
170	            credits: parseInt(form.credits),
171	            billing_type: form.billing_type,
172	            description: form.description,
173	          });
174	          const dodoProductId = dodoResult.product_id;
175	          if (dodoProductId) {
176	            const updateData: any = { dodo_product_id: dodoProductId };
177	            if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
178	            await supabase.from("plans").update(updateData as Record<string, unknown>).eq("id", inserted.id);
179	            toast.success("Plan saved & synced with Dodo ✓");
180	          } else {
181	            toast.success("Plan saved (Dodo sync returned no product ID)");
182	          }
183	        } catch (dodoErr: any) {
184	          toast.warning("Plan saved locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
185	        }
186	      } else {
187	        const { error } = await supabase.from("plans").update(payload).eq("id", editPlan.id);
188	        if (error) { toast.error(error.message); return; }
189	
190	        if (editPlan.dodo_product_id) {
191	          try {
192	            const verification = await syncDodoProduct("verify", {
193	              product_id: editPlan.dodo_product_id,
194	            });
195	
196	            if (!verification.exists) {
197	              await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null } as Record<string, unknown>).eq("id", editPlan.id);
198	              const recreated = await syncDodoProduct("create", {
199	                name: form.name.trim(),
200	                price: parseFloat(form.price),
201	                credits: parseInt(form.credits),
202	                billing_type: form.billing_type,
203	                description: form.description,
204	              });
205	              if (recreated.product_id) {
206	                const updateData: any = { dodo_product_id: recreated.product_id };
207	                if (recreated.credit_entitlement_id) updateData.dodo_credit_entitlement_id = recreated.credit_entitlement_id;
208	                await supabase.from("plans").update(updateData as Record<string, unknown>).eq("id", editPlan.id);
209	              }
210	              toast.success("Missing Dodo product was re-created and linked ✓");
211	            } else {
212	              const dodoResult = await syncDodoProduct("update", {
213	                product_id: editPlan.dodo_product_id,
214	                name: form.name.trim(),
215	                price: parseFloat(form.price),
216	                credits: parseInt(form.credits),
217	                billing_type: form.billing_type,
218	                description: form.description,
219	              });
220	
221	              if (dodoResult.credit_entitlement_id) {
222	                await supabase.from("plans").update({ dodo_credit_entitlement_id: dodoResult.credit_entitlement_id } as Record<string, unknown>).eq("id", editPlan.id);
223	              }
224	              toast.success("Plan updated & synced with Dodo ✓");
225	            }
226	          } catch (dodoErr: any) {
227	              toast.warning("Plan updated locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
228	          }
229	        } else {
230	          try {
231	            const dodoResult = await syncDodoProduct("create", {
232	              name: form.name.trim(),
233	              price: parseFloat(form.price),
234	              credits: parseInt(form.credits),
235	              billing_type: form.billing_type,
236	              description: form.description,
237	            });
238	            const dodoProductId = dodoResult.product_id;
239	            if (dodoProductId) {
240	              const updateData: any = { dodo_product_id: dodoProductId };
241	              if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
242	              await supabase.from("plans").update(updateData as Record<string, unknown>).eq("id", editPlan.id);
243	              toast.success("Plan updated & linked to Dodo ✓");
244	            } else {
245	              toast.success("Plan updated");
246	            }
247	          } catch (dodoErr: any) {
248	            toast.warning("Plan updated but Dodo link failed: " + (dodoErr.message || "Unknown error"));
249	          }
250	        }
251	      }
252	
253	      logAuditAction(
254	        editPlan === "new" ? "plan.create" : "plan.update",
255	        "plan",
256	        editPlan === "new" ? undefined : editPlan.id,
257	        { name: form.name, price: form.price, credits: form.credits },
258	      );
259	      qc.invalidateQueries({ queryKey: ["admin_plans"] });
260	      setEditPlan(null);
261	    } finally {
262	      setSaving(false);
263	    }
264	  };
265	
266	  const handleArchive = async (plan: any) => {
267	    if (plan.dodo_product_id) {
268	      try {
269	        const v = await syncDodoProduct("verify", { product_id: plan.dodo_product_id });
270	        if (v.exists) {
271	          await syncDodoProduct("deactivate", { product_id: plan.dodo_product_id, credit_entitlement_id: plan.dodo_credit_entitlement_id });
272	        } else {
273	          await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null } as Record<string, unknown>).eq("id", plan.id);
274	        }
275	      } catch { /* continue */ }
276	    }
277	    const { error } = await supabase.from("plans").update({ active: false } as Record<string, unknown>).eq("id", plan.id);
278	    if (error) { toast.error(error.message); return; }
279	    toast.success(`"${plan.name}" archived`);
280	    logAuditAction("plan.archive", "plan", plan.id, { name: plan.name });
281	    qc.invalidateQueries({ queryKey: ["admin_plans"] });
282	  };
283	
284	  const handleRestore = async (plan: any) => {
285	    if (plan.dodo_product_id) {
286	      try {
287	        const v = await syncDodoProduct("verify", { product_id: plan.dodo_product_id });
288	        if (v.exists) {
289	          await syncDodoProduct("reactivate", { product_id: plan.dodo_product_id, credit_entitlement_id: plan.dodo_credit_entitlement_id });
290	        } else {
291	          await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null } as Record<string, unknown>).eq("id", plan.id);
292	          toast.info("Stale Dodo link cleared — you can re-sync after restore.");
293	        }
294	      } catch { /* continue */ }
295	    }
296	    const { error } = await supabase.from("plans").update({ active: true } as Record<string, unknown>).eq("id", plan.id);
297	    if (error) { toast.error(error.message); return; }
298	    toast.success(`"${plan.name}" restored`);
299	    logAuditAction("plan.restore", "plan", plan.id, { name: plan.name });
300	    qc.invalidateQueries({ queryKey: ["admin_plans"] });
301	  };
302	
303	  const confirmDelete = async () => {
304	    if (!deleteTarget) return;
305	    const count = paymentCounts?.[deleteTarget.id] || 0;
306	    if (count > 0) {
307	      toast.error(`Cannot delete — this plan has ${count} payment(s) linked. It will remain archived.`);
308	      setDeleteTarget(null);
309	      return;
310	    }
311	
312	    if (deleteTarget.dodo_product_id) {
313	      try {
314	        await syncDodoProduct("deactivate", { product_id: deleteTarget.dodo_product_id, credit_entitlement_id: deleteTarget.dodo_credit_entitlement_id });
315	      } catch { /* continue */ }
316	    }
317	
318	    const { error } = await supabase.from("plans").delete().eq("id", deleteTarget.id);
319	    if (error) {
320	      const message = (error as any)?.message ?? "";
321	      const code = (error as any)?.code;
322	      if (code === "23503" || /foreign key/i.test(message)) {
323	        toast.error("Cannot delete — this plan has existing payments linked to it.");
324	      } else {
325	        toast.error(message || "Failed to delete");
326	      }
327	      setDeleteTarget(null);
328	      return;
329	    }
330	    toast.success("Plan permanently deleted");
331	    logAuditAction("plan.delete", "plan", deleteTarget.id, { name: deleteTarget.name });
332	    qc.invalidateQueries({ queryKey: ["admin_plans"] });
333	    setDeleteTarget(null);
334	  };
335	
336	  const DodoBadge = ({ p }: { p: any }) => {
337	    const vr = verifyResults[p.dodo_product_id];
338	    if (!p.dodo_product_id) {
339	      return (
340	        <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-[11px]" onClick={() => handleSyncToDodo(p)} disabled={saving}>
341	          <Link2 className="h-3 w-3 text-amber-500" />
342	          <span className="text-muted-foreground">Sync to Dodo</span>
343	        </Button>
344	      );
345	    }
346	    return (
347	      <Button
348	        variant="ghost"
349	        size="sm"
350	        className="h-6 px-2 gap-1 text-[11px]"
351	        onClick={() => handleVerify(p.id, p.dodo_product_id)}
352	        disabled={verifying === p.dodo_product_id}
353	      >
354	        {verifying === p.dodo_product_id ? (
355	          <Loader2 className="h-3 w-3 animate-spin" />
356	        ) : vr ? (
357	          vr.exists && vr.is_active ? <CheckCircle className="h-3 w-3 text-emerald-600" /> :
358	          vr.exists ? <AlertTriangle className="h-3 w-3 text-amber-500" /> :
359	          <AlertTriangle className="h-3 w-3 text-destructive" />
360	        ) : (
361	          <CheckCircle className="h-3 w-3 text-emerald-600" />
362	        )}
363	        <span>{vr ? (vr.exists && vr.is_active ? "Verified ✓" : vr.exists ? "Inactive on Dodo" : "Not found") : "Linked"}</span>
364	        <RefreshCw className="h-2.5 w-2.5 text-muted-foreground" />
365	      </Button>
366	    );
367	  };
368	
369	  const PlanRow = ({ p, archived = false }: { p: any; archived?: boolean }) => {
370	    const count = paymentCounts?.[p.id] || 0;
371	    return (
372	      <TableRow key={p.id} className={archived ? "opacity-60" : ""}>
373	        <TableCell className="font-medium">
374	          <div className="flex items-center gap-2">
375	            {p.name}
376	            {archived && <Badge variant="outline" className="text-[11px] text-muted-foreground">Archived</Badge>}
377	          </div>
378	        </TableCell>
379	        <TableCell>${p.price}</TableCell>
380	        <TableCell>{p.credits}</TableCell>
381	        <TableCell>${p.per_resume_cost ?? "0.05"}</TableCell>
382	        <TableCell>{p.billing_type}</TableCell>
383	        <TableCell><DodoBadge p={p} /></TableCell>
384	        <TableCell className="flex gap-1">
385	          {archived ? (
386	            <>
387	              <Button variant="ghost" size="icon" title="Restore" onClick={() => handleRestore(p)}>
388	                <RotateCcw className="h-3.5 w-3.5 text-primary" />
389	              </Button>
390	              <Button
391	                variant="ghost"
392	                size="icon"
393	                title={count > 0 ? `${count} payment(s) linked — cannot delete` : "Delete permanently"}
394	                onClick={() => setDeleteTarget({ id: p.id, name: p.name, dodo_product_id: p.dodo_product_id, dodo_credit_entitlement_id: p.dodo_credit_entitlement_id, paymentCount: count })}
395	              >
396	                <Trash2 className={`h-3.5 w-3.5 ${count > 0 ? "text-muted-foreground" : "text-destructive"}`} />
397	              </Button>
398	              {count > 0 && <span className="text-[11px] text-destructive self-center">{count} payments</span>}
399	            </>
400	          ) : (
401	            <>
402	              <Button variant="ghost" size="icon" onClick={() => openEdit(p)}><Pencil className="h-3.5 w-3.5" /></Button>
403	              <Button variant="ghost" size="icon" title="Archive" onClick={() => handleArchive(p)}>
404	                <Archive className="h-3.5 w-3.5 text-muted-foreground" />
405	              </Button>
406	            </>
407	          )}
408	        </TableCell>
409	      </TableRow>
410	    );
411	  };
412	
413	  return (
414	    <>
415	      <Card>
416	        <CardHeader className="flex flex-row items-center justify-between pb-3">
417	          <CardTitle className="text-lg">Subscription Plans</CardTitle>
418	          <Dialog open={editPlan !== null} onOpenChange={(o) => !o && setEditPlan(null)}>
419	            <DialogTrigger asChild>
420	              <Button size="sm" onClick={openNew}><Plus className="h-4 w-4 mr-1" />Add Plan</Button>
421	            </DialogTrigger>
422	            <DialogContent aria-describedby="plan-dialog-desc">
423	              <DialogHeader>
424	                <DialogTitle>{editPlan === "new" ? "New Plan" : "Edit Plan"}</DialogTitle>
425	                <DialogDescription id="plan-dialog-desc">
426	                  {editPlan === "new" ? "Create a new subscription plan synced with Dodo Payments." : "Update this plan. Changes sync automatically with Dodo."}
427	                </DialogDescription>
428	              </DialogHeader>
429	              <div className="space-y-3">
430	                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Pro Monthly" /></div>
431	                <div><Label>Description</Label><Textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Brief plan description (shown on Dodo)" rows={2} /></div>
432	                <div className="grid grid-cols-2 gap-3">
433	                  <div><Label>Price ($)</Label><Input type="number" min="0.01" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
434	                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
435	                </div>
436	                <div className="grid grid-cols-2 gap-3">
437	                  <div><Label>Billing Type</Label><Input value={form.billing_type} onChange={(e) => setForm({ ...form, billing_type: e.target.value })} /></div>
438	                  <div><Label>Per Resume Cost ($)</Label><Input type="number" step="0.01" min="0" value={form.per_resume_cost} onChange={(e) => setForm({ ...form, per_resume_cost: e.target.value })} /></div>
439	                </div>
440	                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>
441	
442	                {/* Dodo IDs (read-only when editing) */}
443	                {editPlan && editPlan !== "new" && (editPlan.dodo_product_id || editPlan.dodo_credit_entitlement_id) && (
444	                  <div className="bg-muted/50 rounded-md px-3 py-2 space-y-1">
445	                    <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider">Dodo Integration</p>
446	                    {editPlan.dodo_product_id && (
447	                      <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
448	                        <span>Product:</span>
449	                        <code className="bg-background px-1.5 py-0.5 rounded text-[11px] font-mono">{editPlan.dodo_product_id}</code>
450	                        <a href={`https://app.dodopayments.com/products/edit?id=${editPlan.dodo_product_id}`} target="_blank" rel="noopener noreferrer">
451	                          <ExternalLink className="h-3 w-3 text-primary" />
452	                        </a>
453	                      </div>
454	                    )}
455	                    {editPlan.dodo_credit_entitlement_id && (
456	                      <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
457	                        <span>Credit Entitlement:</span>
458	                        <code className="bg-background px-1.5 py-0.5 rounded text-[11px] font-mono">{editPlan.dodo_credit_entitlement_id}</code>
459	                      </div>
460	                    )}
461	                  </div>
462	                )}
463	
464	                <p className="text-xs text-muted-foreground bg-muted rounded-md px-3 py-2">
