554	// ── Custom Field Input renderer ─────────────────────────────────────────────
555	
556	interface CustomFieldInputProps {
557	  field: JobFormField;
558	  value: string | boolean | string[] | undefined;
559	  onChange: (val: string | boolean | string[]) => void;
560	  error?: string;
561	  disabled: boolean;
562	}
563	
564	function CustomFieldInput({
565	  field,
566	  value,
567	  onChange,
568	  error,
569	  disabled,
570	}: CustomFieldInputProps) {
571	  const fieldId = `custom-${field.id}`;
572	  const strVal = typeof value === "string" ? value : "";
573	  const boolVal = typeof value === "boolean" ? value : false;
574	  const arrVal = Array.isArray(value) ? value : [];
575	
576	  return (
577	    <div className="space-y-1.5">
578	      <Label htmlFor={fieldId}>
579	        {field.label}
580	        {field.required && <span className="text-destructive ml-1">*</span>}
581	      </Label>
582	
583	      {field.field_type === "text" && (
584	        <Input
585	          id={fieldId}
586	          type="text"
587	          placeholder={field.placeholder ?? ""}
588	          value={strVal}
589	          onChange={(e) => onChange(e.target.value)}
590	          aria-invalid={!!error}
591	          disabled={disabled}
592	        />
593	      )}
594	
595	      {field.field_type === "number" && (
596	        <Input
597	          id={fieldId}
598	          type="number"
599	          placeholder={field.placeholder ?? ""}
600	          value={strVal}
601	          onChange={(e) => onChange(e.target.value)}
602	          aria-invalid={!!error}
603	          disabled={disabled}
604	        />
605	      )}
606	
607	      {field.field_type === "url" && (
608	        <Input
609	          id={fieldId}
610	          type="url"
611	          placeholder={field.placeholder ?? "https://"}
612	          value={strVal}
613	          onChange={(e) => onChange(e.target.value)}
614	          aria-invalid={!!error}
615	          disabled={disabled}
616	        />
617	      )}
618	
619	      {field.field_type === "date" && (
620	        <Input
621	          id={fieldId}
622	          type="date"
623	          value={strVal}
624	          onChange={(e) => onChange(e.target.value)}
625	          aria-invalid={!!error}
626	          disabled={disabled}
627	        />
628	      )}
629	
630	      {field.field_type === "textarea" && (
631	        <Textarea
632	          id={fieldId}
633	          placeholder={field.placeholder ?? ""}
634	          value={strVal}
635	          onChange={(e) => onChange(e.target.value)}
636	          aria-invalid={!!error}
637	          disabled={disabled}
638	          rows={4}
639	          className="resize-none"
640	        />
641	      )}
642	
643	      {field.field_type === "checkbox" && (
644	        <div className="flex items-center gap-2">
645	          <Checkbox
646	            id={fieldId}
647	            checked={boolVal}
648	            onCheckedChange={(checked) => onChange(!!checked)}
649	            aria-invalid={!!error}
650	            disabled={disabled}
651	          />
652	          <Label htmlFor={fieldId} className="text-sm font-normal cursor-pointer">
653	            {field.placeholder ?? "Yes"}
654	          </Label>
655	        </div>
656	      )}
657	
658	      {field.field_type === "select" && (
659	        <Select
660	          value={strVal}
661	          onValueChange={onChange}
662	          disabled={disabled}
663	        >
664	          <SelectTrigger id={fieldId} aria-invalid={!!error}>
665	            <SelectValue placeholder={field.placeholder ?? "Select an option"} />
666	          </SelectTrigger>
667	          <SelectContent>
668	            {(field.options ?? []).map((opt) => (
669	              <SelectItem key={opt} value={opt}>
670	                {opt}
671	              </SelectItem>
672	            ))}
673	          </SelectContent>
674	        </Select>
675	      )}
676	
677	      {field.field_type === "multiselect" && (
678	        <div className="space-y-1.5">
679	          {(field.options ?? []).map((opt) => (
680	            <div key={opt} className="flex items-center gap-2">
681	              <Checkbox
682	                id={`${fieldId}-${opt}`}
683	                checked={arrVal.includes(opt)}
684	                onCheckedChange={(checked) => {
685	                  if (checked) {
686	                    onChange([...arrVal, opt]);
687	                  } else {
688	                    onChange(arrVal.filter((v) => v !== opt));
689	                  }
690	                }}
691	                disabled={disabled}
692	              />
693	              <Label
694	                htmlFor={`${fieldId}-${opt}`}
695	                className="text-sm font-normal cursor-pointer"
696	              >
697	                {opt}
