122	      if (error) {
123	        if (error.code === "23505") {
124	          toast.info("You're already subscribed to job alerts.");
125	        } else {
126	          throw error;
127	        }
128	      } else {
129	        setSubscribed(true);
130	        toast.success("Subscribed! We'll notify you about new positions.");
131	      }
132	    } catch (err: unknown) {
133	      const msg = err instanceof Error ? err.message : "Failed to subscribe";
134	      toast.error(msg);
135	    } finally {
136	      setSubmitting(false);
137	    }
138	  };
139	
140	  if (subscribed) {
141	    return (
142	      <section className="py-12 border-t border-border bg-muted/30 dark:bg-muted/10">
