33	function getInitials(email?: string | null, fullName?: string | null): string {
34	  if (fullName) {
35	    const parts = fullName.trim().split(/\s+/);
36	    if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
37	    return parts[0][0]?.toUpperCase() ?? "?";
38	  }
39	  if (!email) return "?";
40	  const local = email.split("@")[0];
41	  const parts = local.split(/[._-]/);
42	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
43	  return local[0]?.toUpperCase() ?? "?";
44	}
